def write_notes_markdown(root, order, titles):
    sections = ["# Speaker notes\n", "Short English prompts for the current 26-slide presentation.\n"]
    for page, source_id in enumerate(order, 1):
        sections.append(f"## {page:02d}. {titles[source_id]}\n\n{NOTES[source_id]}\n")
    (root / 'speaker-notes.md').write_text('\n'.join(sections))
